+++ b/src/sendfile/sendfilewizard.cpp
@@ -18,12 +18,15 @@
 #include "pages/selectfilespage.h"

 #include <QApplication>
+#include <QDir>
+#include <QFileInfo>
 #include <QPushButton>
 #include <QUrl>

 #include <KIO/JobTracker>
 #include <KLocalizedString>
 #include <KStatusBarJobTracker>
+#include <KZip>

 #include <BluezQt/Adapter>
 #include <BluezQt/Device>
@@ -89,6 +92,11 @@ void SendFileWizard::setFiles(const QStringList &files)
     m_files = files;
 }

+void SendFileWizard::setCompressFiles(bool compress)
+{
+    m_compressFiles = compress;
+}
+
 BluezQt::DevicePtr SendFileWizard::device() const
 {
     return m_device;
@@ -111,7 +119,20 @@ void SendFileWizard::startTransfer(const QDBusObjectPath &session)
         return;
     }

-    m_job = new SendFilesJob(m_files, m_device, session);
+    QStringList files = m_files;
+    if (m_compressFiles) {
+        const QString archive = createArchive();
+        if (archive.isEmpty()) {
+            next();
+            return;
+        }
+        files = {archive};
+    }
+
+    m_job = new SendFilesJob(files, m_device, session);
+    connect(m_job, &SendFilesJob::finished, this, [this] {
+        m_archiveDir.reset();
+    });
     connect(m_job, &SendFilesJob::destroyed, qApp, &QCoreApplication::quit);

     KIO::getJobTracker()->registerJob(m_job);
@@ -120,6 +141,33 @@ void SendFileWizard::startTransfer(const QDBusObjectPath &session)
     done(1);
 }

+QString SendFileWizard::createArchive()
+{
+    const QFileInfo firstFile(m_files.first());
+    QString archiveName = m_files.count() == 1 ? firstFile.completeBaseName() : firstFile.absoluteDir().dirName();
+    if (archiveName.isEmpty()) {
+        archiveName = i18nc("@item default name of the archive with the sent files", "Files");
+    }
+
+    m_archiveDir = std::make_unique<QTemporaryDir>();
+    KZip zip(m_archiveDir->filePath(archiveName + QStringLiteral(".zip")));
+
+    bool ok = m_archiveDir->isValid() && zip.open(QIODevice::WriteOnly);
+    for (const QString &file : std::as_const(m_files)) {
+        ok = ok && zip.addLocalFile(file, QFileInfo(file).fileName());
+    }
+    ok = zip.close() && ok;
+
+    if (!ok) {
+        qCWarning(BLUEDEVIL_SENDFILE_LOG) << "Error creating archive" << zip.fileName() << zip.errorString();
+        m_failPage->setErrorMessage(i18n("The files could not be compressed: %1", zip.errorString()));
+        m_archiveDir.reset();
+        return QString();
+    }
+
+    return zip.fileName();
+}
+
 void SendFileWizard::initJobResult(BluezQt::InitManagerJob *job)
 {
     if (job->error()) {
@@ -190,7 +238,8 @@ void SendFileWizard::initWizard()
     }

     addPage(new ConnectingPage(this));
-    addPage(new FailPage(this));
